WITH base AS (SELECT * FROM payments WHERE amount >= 740), payments_stats AS (SELECT CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END AS paid_cohort, COUNT(*) AS cnt FROM base GROUP BY CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT paid_cohort, cnt FROM payments_stats ORDER BY paid_cohort, cnt DESC LIMIT 50;
